```
def get_incident_alerts_by_incident_id(
    tenant_id: str, incident_id: str, limit: Optional[int] = None, offset: Optional[int] = None
) -> (List[Alert], int):
    with Session(engine) as session:
        query = (
            session.query(
                Alert,
            )
            .join(AlertToIncident, AlertToIncident.alert_id == Alert.id)
            .join(Incident, AlertToIncident.incident_id == Incident.id)
            .filter(
                AlertToIncident.tenant_id == tenant_id,
                Incident.id == incident_id,
            )
            .order_by(col(Alert.timestamp).desc())
        )

    total_count = query.count()

    if limit and offset:
        query = query.limit(limit).offset(offset)

    return query.all(), total_count
